{v:'VER',what:'cloud-coop-late-body-boss-range: THE OVERSEER and sentries made after the raid build reach player 2 with the boss mark and their real reach (beam, charge lane, sentry lane as long as the host)',
 run:function(){
   if(!(window.__state&&window.__endRaid&&window.__runPrep&&window.__topClear)) return 'SKIP: no raid here';
   if(typeof arcadeDeploy!=='function'||typeof ARCADE!=='object'||typeof netOnMsg!=='function'||typeof bossTick!=='function'||typeof netEntsTick!=='function'||typeof overseerBeam!=='function'||typeof telegraphLane!=='function'||typeof mkSentry!=='function') return 'SKIP: no arcade, party or Overseer in this fixture';
   var g=null, p=null, NK={}, k, oSF=netSendFast, oS=netSend, oB=netBroadcast, oSay=say, sent=[], h={seat:0,state:'in'}, hp={seat:1,state:'in'}, staged=false, oIv=null, opx=0, opy=0;
   var ov, nw, hostMap, p2Map, mo, best=null, gx, gy, a, X, Y, bH, bM, tH, tM, hs, sw, ms, i, ix;
   function cap(m){ sent.push(JSON.parse(JSON.stringify(m))); }
   try{
     __topClear(); __runPrep();
     if(ARCADE.on) return 'SKIP: the arcade is on after __topClear';
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: arcadeDeploy built no arcade raid';
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     p=g.player; oIv=p.iv; p.iv=99; opx=p.x; opy=p.y;
     for(k in NET) NK[k]=NET[k]; staged=true;
     NET.on=true; NET.max=4; NET.specG=null; NET.up=[]; NET.upSeed=g.seed>>>0;
     NET.role='host'; NET.seat=0; NET.peers=[hp];
     netSendFast=function(q,m){ cap(m); return true; }; netSend=function(q,m){ cap(m); return true; }; netBroadcast=function(m){ cap(m); return 1; };
     say=function(){};
     netEntsInit(g);
     g.t=Math.max(g.t||0,3); g.bossDone=0;
     ov=bossTick(true);
     if(!ov||!ov.boss) return 'SKIP: bossTick(true) made no Overseer';
     hs=mkSentry(p.x+200,p.y);
     if(!hs) return 'SKIP: mkSentry made no sentry';
     if(g.ents.indexOf(hs)<0) g.ents.push(hs);
     sent.length=0; netEntsTick();
     nw=null; sw=null;
     for(i=0;i<sent.length;i++){ if(sent[i].t==='ent'&&sent[i].op==='new'&&sent[i].id===ov.nid) nw=sent[i]; if(sent[i].t==='ent'&&sent[i].op==='new'&&sent[i].id===hs.nid) sw=sent[i]; }
     if(!nw||!sw) return 'the host sent no new word for the Overseer or the late sentry';
     hostMap=NET.entMap; NET.entMap={};
     NET.role='join'; NET.seat=1; NET.peers=[h];
     netOnMsg(h,JSON.stringify(nw)); netOnMsg(h,JSON.stringify(sw));
     mo=NET.entMap[ov.nid]; ms=NET.entMap[hs.nid]; p2Map=NET.entMap;
     NET.entMap=hostMap; NET.role='host'; NET.seat=0; NET.peers=[hp];
     if(!mo||!ms) return 'player 2 window made no body from the new word';
     if(mo.boss!==1) return 'player 2 Overseer has no boss mark (boss '+mo.boss+'), so his sweep laser is never drawn and his armour reads wrong';
     if(mo.rng!==ov.rng) return 'player 2 Overseer reach is '+mo.rng+', the host '+ov.rng;
     if(ms.rng!==hs.rng) return 'player 2 late sentry reach is '+ms.rng+', the host '+hs.rng;
     for(gx=-1200;gx<=1200&&!best;gx+=150) for(gy=-1200;gy<=1200&&!best;gy+=150) for(a=0;a<6.28&&!best;a+=0.3927){
       X=opx+gx; Y=opy+gy; if(!spotFree(g.map,X,Y,50)) continue;
       if(rayHitG(X,Y,Math.cos(a),Math.sin(a),1150)>=1140) best={x:X,y:Y,a:a};
     }
     if(!best) return 'SKIP: no open lane on this map';
     ov.x=mo.x=best.x; ov.y=mo.y=best.y; ov.face=mo.face=best.a; ov.seen=mo.seen=1;
     p.x=best.x-Math.cos(best.a)*1500; p.y=best.y-Math.sin(best.a)*1500;
     ov.swpT=mo.swpT=1.5;
     bH=overseerBeam(ov); bM=overseerBeam(mo);
     if(!bH||!bM||Math.round(bH.len)!==Math.round(bM.len)) return 'player 2 Overseer sweep laser is '+(bM&&Math.round(bM.len))+' long, the host '+(bH&&Math.round(bH.len));
     ov.swpT=mo.swpT=0; ov.windup=mo.windup=0.35;
     tH=telegraphLane(ov); tM=telegraphLane(mo);
     if(!tH||!tM||Math.round(tH.len)!==Math.round(tM.len)||tH.w!==tM.w) return 'player 2 Overseer charge lane is '+(tM&&Math.round(tM.len))+' long and '+(tM&&tM.w)+' wide, the host '+(tH&&Math.round(tH.len))+' and '+(tH&&tH.w);
     ov.windup=mo.windup=null;
     hs.x=ms.x=best.x; hs.y=ms.y=best.y; hs.face=ms.face=best.a; hs.windup=ms.windup=0.2;
     tH=telegraphLane(hs); tM=telegraphLane(ms);
     if(!tH||!tM||Math.round(tH.len)!==Math.round(tM.len)) return 'player 2 late sentry lane is '+(tM&&Math.round(tM.len))+' long, the host '+(tH&&Math.round(tH.len));
     return null;
   }catch(e){ return 'threw: '+(e&&e.message||e); }
   finally{
     netSendFast=oSF; netSend=oS; netBroadcast=oB; say=oSay;
     try{ if(g&&g.ents){ if(mo){ ix=g.ents.indexOf(mo); if(ix>=0) g.ents.splice(ix,1); } if(ms){ ix=g.ents.indexOf(ms); if(ix>=0) g.ents.splice(ix,1); } } }catch(_s){}
     if(staged){ for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; }
     if(p){ if(oIv!==null) p.iv=oIv; p.x=opx; p.y=opy; }
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     __topClear();
   }
 }},
